UPDATE t_file_storage_bucket
SET last_check_time = #{checkedAt}, last_check_result = #{result}, version = version + 1,
    update_time = #{checkedAt}
WHERE bucket_id = #{row.bucketId} AND version = #{row.version}

UPDATE t_file_storage_bucket
SET status = #{status}, version = version + 1, update_time = #{now}
WHERE bucket_id = #{row.bucketId} AND version = #{row.version} AND status = #{row.status}
